import type { ProviderCapabilities } from '../../core/capabilities.js';
import { lines, oneLine, SDK_PACKAGE, type GeneratedFile } from './shared.js';

/**
 * Skydo has no API, so its integration has a different shape from the card/UPI gateways:
 * an invoice (Zoho Books bridge) or bank-transfer instructions (ledger mode) instead of a checkout,
 * and status polling (Zoho) or an admin "money arrived" action (ledger) instead of webhooks.
 */

const SERVICE = `/**
 * Skydo payments (generated by ${SDK_PACKAGE}).
 *
 * Skydo has no developer API or webhooks. The SDK automates the two paths Skydo supports:
 *  - Zoho Books bridge (ZOHO_* set): we create a Zoho invoice; Skydo imports it, and marks it paid
 *    (with the FIRA attached) when the money arrives. We poll Zoho for that status.
 *  - Ledger mode (only SKYDO_RECEIVING_ACCOUNTS set): we hand the client your Skydo account details
 *    with the order reference; an admin records the receipt when Skydo notifies you.
 */
import { createPaymentsClient, PaymentError, toMajorString, type PaymentStatus } from '${SDK_PACKAGE}';

export const payments = createPaymentsClient({ actor: 'app:skydo' });

export interface ExportInvoice {
  /** 3-40 chars, letters/digits/_/-. Used as Zoho reference_number and the bank transfer reference. */
  orderRef: string;
  /** Minor units of the client's currency: USD 1,250.00 = 125000. Skydo minimum is USD 50. */
  amount: number;
  currency: string;
  customer: { name?: string; email: string };
  description: string;
  status: PaymentStatus;
  fulfilled: boolean;
}

// TODO: replace with your database (an invoices / orders table).
const invoices = new Map<string, ExportInvoice>();

export async function loadInvoice(orderRef: string): Promise<ExportInvoice | undefined> {
  return invoices.get(orderRef);
}

async function saveInvoice(inv: ExportInvoice): Promise<void> {
  invoices.set(inv.orderRef, inv);
}

/** Called once per invoice. MUST be idempotent: polling and admin actions can both reach it. */
async function onPaid(inv: ExportInvoice): Promise<void> {
  // TODO: mark the order paid, release deliverables, email the client a receipt.
  console.log(\`Skydo payment received for \${inv.orderRef}: \${inv.currency} \${toMajorString(inv.amount, inv.currency)}\`);
}

/** Create the invoice (Zoho bridge) or payment instructions (ledger mode) for an order YOU priced. */
export async function requestPayment(inv: Omit<ExportInvoice, 'status' | 'fulfilled'>) {
  const created = await payments.createPayment('skydo', {
    orderRef: inv.orderRef,
    amount: inv.amount,
    currency: inv.currency,
    customer: inv.customer,
    description: inv.description,
  });
  await saveInvoice({ ...inv, status: created.status, fulfilled: false });
  // checkout.type is always "manual" for Skydo: instructions for your client (+ the Zoho invoice link).
  if (created.checkout.type !== 'manual') throw new Error('unexpected checkout type');
  return { orderRef: inv.orderRef, instructions: created.checkout.instructions, invoiceUrl: created.checkout.url };
}

/** Read the authoritative status (Zoho invoice or ledger) and fulfil exactly once. */
export async function refreshStatus(orderRef: string): Promise<PaymentStatus> {
  const inv = await loadInvoice(orderRef);
  if (!inv) throw new PaymentError('NOT_FOUND', \`Unknown invoice \${orderRef}\`);
  const v = await payments.verifyPayment('skydo', { orderRef, expectedAmount: inv.amount, payload: {} });
  inv.status = v.status;
  if (v.paid && !inv.fulfilled) {
    inv.fulfilled = true;
    await saveInvoice(inv);
    await onPaid(inv);
  } else {
    await saveInvoice(inv);
  }
  return inv.status;
}

/**
 * Zoho bridge: Skydo has no webhooks, so poll unpaid invoices. Skydo syncs with Zoho about every
 * 10 minutes, so polling every 15 minutes is plenty (Zoho allows 100 requests/minute per org).
 */
export async function pollUnpaid(): Promise<void> {
  for (const inv of invoices.values()) {
    if (inv.fulfilled || inv.status === 'cancelled') continue;
    try {
      await refreshStatus(inv.orderRef);
    } catch (err) {
      payments.logger.warn('skydo.poll_failed', { orderRef: inv.orderRef, err: String(err) });
    }
  }
}

/**
 * Ledger mode: an admin confirms money Skydo told you arrived. Check it in the Skydo dashboard first.
 * receiptId = the Skydo transaction reference (or FIRA number): recording it twice is a no-op.
 */
export async function recordReceipt(input: { orderRef: string; receiptId: string; amountReceived: number; firaNumber?: string; note?: string }) {
  await payments.skydoRecordPayment(input);
  return refreshStatus(input.orderRef);
}

/** Cheap status for customers/front-ends: our own record only, never a Zoho call (protects your Zoho API quota). */
export async function storedStatus(orderRef: string): Promise<PaymentStatus | undefined> {
  return (await loadInvoice(orderRef))?.status;
}

/** Ledger mode: what clients still owe you, oldest first. */
export async function outstanding() {
  return payments.skydoOutstanding();
}
`;

const ADMIN_CHECK = `import { timingSafeEqual } from 'node:crypto';

/** Replace with your real admin auth. Recording a receipt marks an order paid. */
export function assertAdmin(authorization: string | undefined): void {
  const token = process.env.ADMIN_API_TOKEN ?? '';
  const got = Buffer.from((authorization ?? '').replace(/^Bearer\\s+/i, ''));
  const want = Buffer.from(token);
  if (!token || got.length !== want.length || !timingSafeEqual(got, want)) {
    throw Object.assign(new Error('Forbidden'), { status: 403 });
  }
}
`;

function expressRoutes(): string {
  return `import express, { type NextFunction, type Request, type Response } from 'express';
import { PaymentError } from '${SDK_PACKAGE}';
import { assertAdmin } from './admin.js';
import { outstanding, pollUnpaid, recordReceipt, refreshStatus, requestPayment, storedStatus } from './skydo.js';

export const skydoRouter = express.Router();
skydoRouter.use(express.json());

const wrap = (fn: (req: Request, res: Response) => Promise<unknown>) => (req: Request, res: Response, next: NextFunction) => fn(req, res).catch(next);

// Create the invoice / payment instructions. Price it on the SERVER, never from the request body.
skydoRouter.post('/api/skydo/invoices', wrap(async (req, res) => {
  const { orderId } = req.body as { orderId?: string };
  if (!orderId) return void res.status(400).json({ error: 'orderId required' });
  // TODO: load the order from your database. Example values:
  const order = { amount: 125000, currency: 'USD', customer: { name: 'Globex Corp', email: 'ap@globex.example' }, description: 'Design retainer, March' };
  res.status(201).json(await requestPayment({ orderRef: orderId, ...order }));
}));

// Public: answers from your own records. The poller (or the admin refresh below) updates them.
skydoRouter.get('/api/skydo/invoices/:orderRef', wrap(async (req, res) => {
  const status = await storedStatus(String(req.params.orderRef));
  if (!status) return void res.status(404).json({ error: 'NOT_FOUND' });
  res.json({ orderRef: req.params.orderRef, status });
}));

// Admin: re-read the authoritative status now (Zoho invoice or ledger).
skydoRouter.post('/api/skydo/invoices/:orderRef/refresh', wrap(async (req, res) => {
  assertAdmin(req.get('authorization'));
  res.json({ orderRef: req.params.orderRef, status: await refreshStatus(String(req.params.orderRef)) });
}));

// Ledger mode only: an admin records money Skydo said arrived.
skydoRouter.post('/api/skydo/receipts', wrap(async (req, res) => {
  assertAdmin(req.get('authorization'));
  const { orderRef, receiptId, amountReceived, firaNumber, note } = req.body as { orderRef: string; receiptId: string; amountReceived: number; firaNumber?: string; note?: string };
  res.json({ orderRef, status: await recordReceipt({ orderRef, receiptId, amountReceived, firaNumber, note }) });
}));

skydoRouter.get('/api/skydo/outstanding', wrap(async (req, res) => {
  assertAdmin(req.get('authorization'));
  res.json(await outstanding());
}));

skydoRouter.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
  if (err instanceof PaymentError) return void res.status(err.code === 'NOT_FOUND' ? 404 : 400).json(err.toJSON());
  const status = (err as { status?: number }).status ?? 500;
  res.status(status).json({ error: status === 403 ? 'FORBIDDEN' : 'INTERNAL' });
});

/** Zoho bridge: start polling. Ledger mode needs no polling (an admin records receipts). */
export function startSkydoPolling(intervalMs = 15 * 60_000) {
  return setInterval(() => void pollUnpaid(), intervalMs);
}
`;
}

function expressServer(): string {
  return `import express from 'express';
import { skydoRouter, startSkydoPolling } from './payments/skydo-routes.js';

const app = express();
app.use(skydoRouter);
const port = Number(process.env.PORT ?? 3000);
app.listen(port, () => console.log(\`Skydo payments on http://localhost:\${port}\`));
if (process.env.ZOHO_REFRESH_TOKEN) startSkydoPolling();
`;
}

function nextRoutes(): GeneratedFile[] {
  const imp = `import { NextResponse } from 'next/server';
import { PaymentError } from '${SDK_PACKAGE}';`;
  const errors = `function fail(err: unknown) {
  if (err instanceof PaymentError) return NextResponse.json(err.toJSON(), { status: err.code === 'NOT_FOUND' ? 404 : 400 });
  const status = (err as { status?: number }).status ?? 500;
  return NextResponse.json({ error: status === 403 ? 'FORBIDDEN' : 'INTERNAL' }, { status });
}`;
  return [
    {
      path: 'app/api/skydo/invoices/route.ts',
      language: 'typescript',
      contents: `${imp}
import { requestPayment } from '@/lib/payments/skydo';

export const runtime = 'nodejs';

${errors}

export async function POST(req: Request) {
  try {
    const { orderId } = (await req.json()) as { orderId?: string };
    if (!orderId) return NextResponse.json({ error: 'orderId required' }, { status: 400 });
    // TODO: load the order from your database. Never trust an amount from the browser.
    const order = { amount: 125000, currency: 'USD', customer: { name: 'Globex Corp', email: 'ap@globex.example' }, description: 'Design retainer, March' };
    return NextResponse.json(await requestPayment({ orderRef: orderId, ...order }), { status: 201 });
  } catch (err) {
    return fail(err);
  }
}
`,
    },
    {
      path: 'app/api/skydo/invoices/[orderRef]/route.ts',
      language: 'typescript',
      contents: `${imp}
import { storedStatus } from '@/lib/payments/skydo';

export const runtime = 'nodejs';

${errors}

/** Public: answers from your own records (the poll route keeps them fresh), never calls Zoho. */
export async function GET(_req: Request, { params }: { params: Promise<{ orderRef: string }> }) {
  try {
    const { orderRef } = await params;
    const status = await storedStatus(orderRef);
    if (!status) return NextResponse.json({ error: 'NOT_FOUND' }, { status: 404 });
    return NextResponse.json({ orderRef, status });
  } catch (err) {
    return fail(err);
  }
}
`,
    },
    {
      path: 'app/api/skydo/receipts/route.ts',
      language: 'typescript',
      contents: `${imp}
import { assertAdmin } from '@/lib/payments/admin';
import { recordReceipt } from '@/lib/payments/skydo';

export const runtime = 'nodejs';

${errors}

/** Ledger mode only: an admin records money Skydo said arrived. */
export async function POST(req: Request) {
  try {
    assertAdmin(req.headers.get('authorization') ?? undefined);
    const body = (await req.json()) as { orderRef: string; receiptId: string; amountReceived: number; firaNumber?: string; note?: string };
    return NextResponse.json({ orderRef: body.orderRef, status: await recordReceipt(body) });
  } catch (err) {
    return fail(err);
  }
}
`,
    },
    {
      path: 'app/api/skydo/poll/route.ts',
      language: 'typescript',
      contents: `${imp}
import { assertAdmin } from '@/lib/payments/admin';
import { pollUnpaid } from '@/lib/payments/skydo';

export const runtime = 'nodejs';

${errors}

/** Zoho bridge: call from a cron (e.g. Vercel Cron every 15 min). Skydo has no webhooks. */
export async function POST(req: Request) {
  try {
    assertAdmin(req.headers.get('authorization') ?? undefined);
    await pollUnpaid();
    return NextResponse.json({ ok: true });
  } catch (err) {
    return fail(err);
  }
}
`,
    },
  ];
}

function fastifyPlugin(): string {
  return `import type { FastifyInstance } from 'fastify';
import { PaymentError } from '${SDK_PACKAGE}';
import { assertAdmin } from './admin.js';
import { outstanding, recordReceipt, refreshStatus, requestPayment, storedStatus } from './skydo.js';

export async function skydoRoutes(app: FastifyInstance) {
  app.setErrorHandler((err, _req, reply) => {
    if (err instanceof PaymentError) return reply.code(err.code === 'NOT_FOUND' ? 404 : 400).send(err.toJSON());
    const status = (err as { status?: number }).status ?? 500;
    return reply.code(status).send({ error: status === 403 ? 'FORBIDDEN' : 'INTERNAL' });
  });

  app.post<{ Body: { orderId?: string } }>('/api/skydo/invoices', async (req, reply) => {
    if (!req.body?.orderId) return reply.code(400).send({ error: 'orderId required' });
    // TODO: load the order from your database. Never trust an amount from the browser.
    const order = { amount: 125000, currency: 'USD', customer: { name: 'Globex Corp', email: 'ap@globex.example' }, description: 'Design retainer, March' };
    return reply.code(201).send(await requestPayment({ orderRef: req.body.orderId, ...order }));
  });

  // Public: answers from your own records, never calls Zoho.
  app.get<{ Params: { orderRef: string } }>('/api/skydo/invoices/:orderRef', async (req, reply) => {
    const status = await storedStatus(req.params.orderRef);
    if (!status) return reply.code(404).send({ error: 'NOT_FOUND' });
    return { orderRef: req.params.orderRef, status };
  });

  app.post<{ Params: { orderRef: string } }>('/api/skydo/invoices/:orderRef/refresh', async (req) => {
    assertAdmin(req.headers.authorization);
    return { orderRef: req.params.orderRef, status: await refreshStatus(req.params.orderRef) };
  });

  app.post<{ Body: { orderRef: string; receiptId: string; amountReceived: number; firaNumber?: string; note?: string } }>('/api/skydo/receipts', async (req) => {
    assertAdmin(req.headers.authorization);
    return { orderRef: req.body.orderRef, status: await recordReceipt(req.body) };
  });

  app.get('/api/skydo/outstanding', async (req) => {
    assertAdmin(req.headers.authorization);
    return outstanding();
  });
}
`;
}

export function skydoGuide(cap: ProviderCapabilities): string {
  return lines(
    `# Collecting international payments with Skydo`,
    ``,
    `Skydo has **no public developer API, SDK or webhooks** (checked ${cap.lastVerified}; an API is on Skydo's roadmap).`,
    `Its Terms forbid automating the Skydo dashboard. The generated code therefore never calls Skydo. It automates the two`,
    `paths Skydo itself supports, through the \`${SDK_PACKAGE}\` SDK.`,
    ``,
    `## Option A: Zoho Books bridge (fully automatic, recommended)`,
    ``,
    `1. In Skydo: profile > **Connect Skydo to Zoho** > Connect Securely. Choose all currencies or international only.`,
    `   Only invoices created **after** connecting are imported.`,
    `2. In Zoho Books: create a service item (e.g. "Export services") and note its \`item_id\` (\`ZOHO_ITEM_ID\`).`,
    `   Create each client once as a customer with their billing currency (GST treatment "Overseas" for Indian organisations).`,
    `3. Zoho API Console (api-console.zoho.<region>) > **Self Client** > Generate Code with scope`,
    `   \`ZohoBooks.invoices.ALL,ZohoBooks.contacts.READ\`, then exchange it for a refresh token:`,
    ``,
    '   ```bash',
    `   curl -X POST "https://accounts.zoho.in/oauth/v2/token" \\`,
    `     -d grant_type=authorization_code -d client_id=$ZOHO_CLIENT_ID -d client_secret=$ZOHO_CLIENT_SECRET -d code=<code>`,
    '   ```',
    ``,
    `   Use your region's accounts host: accounts.zoho.com / .eu / .in / .com.au / .jp / .com.cn / .sa / .ae / .uk / .sg,`,
    `   and accounts.zohocloud.ca for Canada. Put the \`refresh_token\` in \`ZOHO_REFRESH_TOKEN\`.`,
    `4. Set the \`ZOHO_*\` variables. \`requestPayment()\` creates the Zoho invoice (reference = your order id) and marks it sent.`,
    `   Skydo imports Zoho invoices within ~10 minutes. **During setup, confirm the first API-created invoice appears in your`,
    `   Skydo dashboard** (Skydo documents Zoho sync but not API-created invoices specifically). When the client pays, Skydo marks`,
    `   it **paid** in Zoho and attaches the **FIRA**. A Zoho "paid" caused by a write-off or credit note is NOT treated as paid.`,
    `   \`pollUnpaid()\` (every 15 min) sees that and calls \`onPaid()\` exactly once.`,
    ``,
    `## Option B: receiving accounts + ledger (no Zoho)`,
    ``,
    `1. Copy your account details from Skydo dashboard > International Accounts into \`SKYDO_RECEIVING_ACCOUNTS\`:`,
    ``,
    '   ```json',
    `   [{"currency":"USD","label":"US account (ACH)","details":{"Account holder":"...","Account number":"...","ACH routing":"..."}},`,
    `    {"currency":"*","label":"SWIFT","details":{"SWIFT/BIC":"...","Account number":"..."}}]`,
    '   ```',
    ``,
    `2. \`requestPayment()\` returns transfer instructions with your order id as the payment reference. Send them to the client`,
    `   (email, invoice PDF). The expected payment is tracked in \`SKYDO_LEDGER_FILE\`.`,
    `3. When Skydo emails/WhatsApps you that money arrived, check it in the Skydo dashboard, then call \`POST /api/skydo/receipts\``,
    `   (admin) with \`receiptId\` (the Skydo transaction reference) and the amount received in cents. Recording the same`,
    `   receiptId twice is a no-op; a short amount (bank fees abroad) keeps the order pending. Match it to the invoice in Skydo too.`,
    ``,
    `## Things Skydo does not support (so neither does this code)`,
    ``,
    `- Checkout on your website, cards/UPI, INR, refunds via API (Skydo cannot refund a settled payment directly), webhooks.`,
    `- Recurring payments: raise one invoice per billing period.`,
    `- Turn off Zoho online payment gateways on these invoices so clients pay through Skydo (and you get a FIRA).`,
    `- Payment links (InstaLinks) exist but are created by hand in the dashboard and are single-use.`,
    ``,
    `## Constraints`,
    ``,
    ...cap.constraints.map((c) => `- ${oneLine(c)}`),
    ``,
  );
}

export function skydoFiles(framework: string): GeneratedFile[] {
  const files: GeneratedFile[] = [];
  if (framework === 'nextjs') {
    files.push({ path: 'lib/payments/skydo.ts', language: 'typescript', contents: SERVICE });
    files.push({ path: 'lib/payments/admin.ts', language: 'typescript', contents: ADMIN_CHECK });
    files.push(...nextRoutes());
  } else if (framework === 'fastify') {
    files.push({ path: 'src/payments/skydo.ts', language: 'typescript', contents: SERVICE });
    files.push({ path: 'src/payments/admin.ts', language: 'typescript', contents: ADMIN_CHECK });
    files.push({ path: 'src/payments/skydo-routes.ts', language: 'typescript', contents: fastifyPlugin() });
  } else {
    // express, react, html, mobile, other: an Express backend holds the Zoho secrets and the ledger.
    files.push({ path: 'src/payments/skydo.ts', language: 'typescript', contents: SERVICE });
    files.push({ path: 'src/payments/admin.ts', language: 'typescript', contents: ADMIN_CHECK });
    files.push({ path: 'src/payments/skydo-routes.ts', language: 'typescript', contents: expressRoutes() });
    files.push({ path: 'src/server.ts', language: 'typescript', contents: expressServer() });
  }
  return files;
}
